SET search_path TO blackboxdb_api, blackboxdb_core, blackboxdb_api_catalog;
SET blackboxdb.next_collection_id TO 26930000;
SET blackboxdb.next_collection_index_id TO 26930000;

-- A missing path compares like null, and null sorts above MinKey and below MaxKey. So $gt/$gte against MinKey
-- and $lt/$lte against MaxKey also match a document without the path (a dotted path follows the null rules
-- through arrays), and their $not forms exclude it. With blackboxdb.enable_minmaxkey_missing_path_match on, every
-- access path returns that answer: a collection scan, the ordered index (c) and a single-path index (c2).
-- Document 9 has no elem; 16 has a subdocument without k. $exists and _id keep their meaning.
SELECT COUNT(*) FROM (SELECT blackboxdb_api.insert_one('minmaxdb', 'c', d::blackboxdb_core.bson) FROM (VALUES
  ('{"_id": 1, "elem": [7, 8]}'),
  ('{"_id": 2, "elem": [9, 10]}'),
  ('{"_id": 3, "elem": 8}'),
  ('{"_id": 4, "elem": 9}'),
  ('{"_id": 5, "elem": null}'),
  ('{"_id": 6, "elem": []}'),
  ('{"_id": 7, "elem": [null]}'),
  ('{"_id": 8, "elem": [null, 9]}'),
  ('{"_id": 9}'),
  ('{"_id": 10, "elem": {"k": 5}}'),
  ('{"_id": 11, "elem": [{"k": 7}]}'),
  ('{"_id": 12, "elem": {"$minKey": 1}}'),
  ('{"_id": 13, "elem": [{"$maxKey": 1}, 9]}'),
  ('{"_id": 14, "elem": {"$maxKey": 1}}'),
  ('{"_id": 15, "elem": [{"$minKey": 1}]}'),
  ('{"_id": 16, "other": 1, "elem": {"j": 1}}')) v(d)) x;
SELECT COUNT(*) FROM (SELECT blackboxdb_api.insert_one('minmaxdb', 'c2', d::blackboxdb_core.bson) FROM (VALUES
  ('{"_id": 1, "elem": [7, 8]}'),
  ('{"_id": 2, "elem": [9, 10]}'),
  ('{"_id": 3, "elem": 8}'),
  ('{"_id": 4, "elem": 9}'),
  ('{"_id": 5, "elem": null}'),
  ('{"_id": 6, "elem": []}'),
  ('{"_id": 7, "elem": [null]}'),
  ('{"_id": 8, "elem": [null, 9]}'),
  ('{"_id": 9}'),
  ('{"_id": 10, "elem": {"k": 5}}'),
  ('{"_id": 11, "elem": [{"k": 7}]}'),
  ('{"_id": 12, "elem": {"$minKey": 1}}'),
  ('{"_id": 13, "elem": [{"$maxKey": 1}, 9]}'),
  ('{"_id": 14, "elem": {"$maxKey": 1}}'),
  ('{"_id": 15, "elem": [{"$minKey": 1}]}'),
  ('{"_id": 16, "other": 1, "elem": {"j": 1}}')) v(d)) x;
SELECT blackboxdb_api_internal.create_indexes_non_concurrently('minmaxdb', '{ "createIndexes": "c", "indexes": [ { "key": { "elem": 1 }, "name": "elem_1", "enableOrderedIndex": 1 } ] }', TRUE);
SELECT blackboxdb_api_internal.create_indexes_non_concurrently('minmaxdb', '{ "createIndexes": "c2", "indexes": [ { "key": { "elem": 1 }, "name": "elem_1", "enableOrderedIndex": false } ] }', TRUE);

-- ids that a find returns, by a collection scan or through the hinted elem index, with the flag off or on
CREATE FUNCTION pg_temp.ids(coll text, filter text, use_index bool, flag bool) RETURNS text LANGUAGE plpgsql AS $fn$
DECLARE spec text; result text;
BEGIN
  spec := '{ "find": "' || coll || '", "filter": ' || filter || ', "projection": { "_id": 1 }' ||
          CASE WHEN use_index THEN ', "hint": "elem_1" }' ELSE ' }' END;
  PERFORM set_config('blackboxdb.enable_minmaxkey_missing_path_match', CASE WHEN flag THEN 'on' ELSE 'off' END, true);
  PERFORM set_config('enable_seqscan', CASE WHEN use_index THEN 'off' ELSE 'on' END, true);
  PERFORM set_config('enable_indexscan', CASE WHEN use_index THEN 'on' ELSE 'off' END, true);
  PERFORM set_config('enable_bitmapscan', CASE WHEN use_index THEN 'on' ELSE 'off' END, true);
  EXECUTE format('SELECT string_agg(i::text, '','' ORDER BY i) FROM (SELECT substring(t.d::text from ''"\$numberInt" : "(\d+)"'')::int AS i FROM (SELECT document AS d FROM bson_aggregation_find(''minmaxdb'', %L::blackboxdb_core.bson)) t) n', spec) INTO result;
  RETURN COALESCE(result, '');
END $fn$;

SELECT 'lte maxkey' AS filter, pg_temp.ids('c', '{"elem": {"$lte": {"$maxKey": 1}}}', false, false) AS off_collection_scan, pg_temp.ids('c', '{"elem": {"$lte": {"$maxKey": 1}}}', true, false) AS off_ordered_index, pg_temp.ids('c', '{"elem": {"$lte": {"$maxKey": 1}}}', false, true) AS collection_scan, pg_temp.ids('c', '{"elem": {"$lte": {"$maxKey": 1}}}', true, true) AS ordered_index, pg_temp.ids('c2', '{"elem": {"$lte": {"$maxKey": 1}}}', true, true) AS single_path_index;
