SELECT 'ctl exists false' AS filter, pg_temp.ids('c', '{"elem": {"$exists": false}}', false, false) AS off_collection_scan, pg_temp.ids('c', '{"elem": {"$exists": false}}', true, false) AS off_ordered_index, pg_temp.ids('c', '{"elem": {"$exists": false}}', false, true) AS collection_scan, pg_temp.ids('c', '{"elem": {"$exists": false}}', true, true) AS ordered_index, pg_temp.ids('c2', '{"elem": {"$exists": false}}', true, true) AS single_path_index;
SELECT 'ctl not exists true' AS filter, pg_temp.ids('c', '{"elem": {"$not": {"$exists": true}}}', false, false) AS off_collection_scan, pg_temp.ids('c', '{"elem": {"$not": {"$exists": true}}}', true, false) AS off_ordered_index, pg_temp.ids('c', '{"elem": {"$not": {"$exists": true}}}', false, true) AS collection_scan, pg_temp.ids('c', '{"elem": {"$not": {"$exists": true}}}', true, true) AS ordered_index, pg_temp.ids('c2', '{"elem": {"$not": {"$exists": true}}}', true, true) AS single_path_index;
SELECT 'ctl nested exists true' AS filter, pg_temp.ids('c', '{"elem.k": {"$exists": true}}', false, false) AS off_collection_scan, pg_temp.ids('c', '{"elem.k": {"$exists": true}}', true, false) AS off_ordered_index, pg_temp.ids('c', '{"elem.k": {"$exists": true}}', false, true) AS collection_scan, pg_temp.ids('c', '{"elem.k": {"$exists": true}}', true, true) AS ordered_index, pg_temp.ids('c2', '{"elem.k": {"$exists": true}}', true, true) AS single_path_index;
SELECT 'ctl elemmatch lte maxkey' AS filter, pg_temp.ids('c', '{"elem": {"$elemMatch": {"$lte": {"$maxKey": 1}}}}', false, false) AS off_collection_scan, pg_temp.ids('c', '{"elem": {"$elemMatch": {"$lte": {"$maxKey": 1}}}}', true, false) AS off_ordered_index, pg_temp.ids('c', '{"elem": {"$elemMatch": {"$lte": {"$maxKey": 1}}}}', false, true) AS collection_scan, pg_temp.ids('c', '{"elem": {"$elemMatch": {"$lte": {"$maxKey": 1}}}}', true, true) AS ordered_index, pg_temp.ids('c2', '{"elem": {"$elemMatch": {"$lte": {"$maxKey": 1}}}}', true, true) AS single_path_index;
SELECT 'ctl elemmatch k lte maxkey' AS filter, pg_temp.ids('c', '{"elem": {"$elemMatch": {"k": {"$lte": {"$maxKey": 1}}}}}', false, false) AS off_collection_scan, pg_temp.ids('c', '{"elem": {"$elemMatch": {"k": {"$lte": {"$maxKey": 1}}}}}', true, false) AS off_ordered_index, pg_temp.ids('c', '{"elem": {"$elemMatch": {"k": {"$lte": {"$maxKey": 1}}}}}', false, true) AS collection_scan, pg_temp.ids('c', '{"elem": {"$elemMatch": {"k": {"$lte": {"$maxKey": 1}}}}}', true, true) AS ordered_index, pg_temp.ids('c2', '{"elem": {"$elemMatch": {"k": {"$lte": {"$maxKey": 1}}}}}', true, true) AS single_path_index;

-- The bound keeps its index scan: the null equality is a second index condition on the same index
SET blackboxdb.enable_minmaxkey_missing_path_match TO on;
SET enable_seqscan TO off;
EXPLAIN (COSTS OFF) SELECT document FROM bson_aggregation_find('minmaxdb', '{ "find": "c", "filter": { "elem": { "$lt": { "$maxKey": 1 } } } }');
EXPLAIN (COSTS OFF) SELECT document FROM bson_aggregation_find('minmaxdb', '{ "find": "c2", "filter": { "elem": { "$gt": { "$minKey": 1 } } } }');
-- _id is never missing, so its bounds stay a plain comparison
EXPLAIN (COSTS OFF) SELECT document FROM bson_aggregation_find('minmaxdb', '{ "find": "c", "filter": { "_id": { "$gte": { "$minKey": 1 }, "$lt": { "$maxKey": 1 } } } }');
RESET enable_seqscan;
RESET blackboxdb.enable_minmaxkey_missing_path_match;
